async function carregarUsuarios(){try{const e=await fetch("/api/admin/usuarios");if(403===e.status||401===e.status)return alert("Você não tem permissão para acessar esta página."),void(window.location.href="/");const a=await e.json();a.sucesso&&renderizarUsuarios(a.dados)}catch{alert("Erro ao carregar dados. Tente novamente.")}}function criarCelula(e){const a=document.createElement("td");return a.textContent=e??"",a}function renderizarUsuarios(e){const a=document.querySelector("#tabelaUsuarios tbody");if(a.replaceChildren(),!e.length){const e=a.insertRow().insertCell();return e.colSpan=7,void(e.textContent="Nenhum usuário encontrado.")}for(const t of e){const e=document.createElement("tr");e.append(criarCelula(t.id),criarCelula(t.nome),criarCelula(t.email),criarCelula(t.saldo_tokens),criarCelula(t.status),criarCelula(t.ganhos_afiliado??0));const n=document.createElement("td"),o=document.createElement("button");o.className="btn btn-warning btn-sm fw-bold",o.textContent="+ Dar Tokens",o.addEventListener("click",()=>darTokens(t.id)),n.className="text-end",n.append(o),e.append(n),a.append(e)}}async function darTokens(e){const a=prompt(`Quantos tokens deseja adicionar ao usuário ID ${e}?`),t=parseInt(a,10);if(!(!a||isNaN(t)||t<=0))try{const a=await fetch("/api/admin/usuarios/tokens",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({usuarioId:e,quantidade:t})}),n=await a.json();n.sucesso?(alert("Tokens adicionados com sucesso!"),carregarUsuarios()):alert(`Erro: ${n.erro}`)}catch{alert("Erro de conexão ao adicionar tokens.")}}document.addEventListener("DOMContentLoaded",carregarUsuarios);